// The real-KJV render golden (src-tauri/tests/golden/kjv-render.json), machine-
// generated by the Rust core from pipeline/out/kjv.sqlite through open_verified.
// Regenerate (in src-tauri): `cargo test -- --ignored regenerate_kjv_render_golden`.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import type { Book, Run } from "../src/lib/types";

export interface KVerse {
  v: number; id: number; text: string; red: [number, number][]; add: [number, number][];
  nd: [number, number][]; words: [number, number, string][]; runs: Run[];
}
export interface KChapter { book: number; osis: string; name: string; chapter: number; verses: KVerse[] }
export interface KGolden {
  translation: { abbrev: string; name: string; has_red_letters: boolean };
  books: Book[];
  chapters: KChapter[];
}
export const kjv: KGolden = JSON.parse(
  readFileSync(resolve(process.cwd(), "src-tauri/tests/golden/kjv-render.json"), "utf8"),
);

